			break;
		case EVOKE:
		case MASK:
		case CROWN:
		case FORGE:
		case STAR:
			texture(Asset.getAssetFilePath(GeneralAsset.STAR));
			break;
		case RATTLE:
		case BONE:
			texture(Asset.getAssetFilePath(GeneralAsset.BONE));
			break;
		case JET:
		case TOXIC:
		case CORROSION:
		case PARALYSIS:
