			lifespan = 0.5f;
			am = 0;
			break;

		case QUESTION:
			lifespan = 0.8f;
			break;

		case UP:
			speed.set( 0, -20 );
			lifespan = 1f;
			break;

		case CALM:
			color(0, 1, 1);
		case SCREAM:
			lifespan = 0.9f;
			break;

		case BONE:
			lifespan = 0.2f;
			speed.polar( Random.Float( 2 * 3.1415926f ), 24 / lifespan );
			acc.set( 0, 128 );
			angle = Random.Float( 360 );
			angularSpeed = 360;
			break;

		case RATTLE:
			lifespan = 0.5f;
			speed.set( 0, -100 );
			acc.set( 0, -2 * speed.y / lifespan );
			angle = Random.Float( 360 );
			angularSpeed = 360;
			break;

		case WOOL:
			lifespan = 0.5f;
			speed.set( 0, -50 );
			angle = Random.Float( 360 );
			angularSpeed = Random.Float( -360, +360 );
			break;

		case ROCK:
			angle = Random.Float( 360 );
