	public AttackIndicator() {
		super( DangerIndicator.COLOR );

		synchronized (this) {
			instance = this;
			lastTarget = null;

			setSize(SIZE, SIZE);
			visible(false);
			enable(false);
		}
	}

	@Override
	public GameAction keyAction() {
		return SPDAction.TAG_ATTACK;
