				return SPDAction.INVENTORY_SELECTOR;
			}

			@Override
			protected String hoverText() {
				return Messages.titleCase(Messages.get(WndKeyBindings.class, "inventory"));
			}

			@Override
			protected boolean onLongClick() {
				GameScene.show(new WndQuickBag(null));
