			}

			@Override
			protected void createChildren() {
				super.createChildren();
				arrow = new Image(Asset.getAssetFilePath(GeneralAsset.ICON_COMPASS));
				arrow.originToCenter();
				arrow.visible = SPDSettings.interfaceSize() == 2;
