public class ItemSprite extends MovieClip {

	public static final int SIZE	= 16;

	private static final float DROP_INTERVAL = 0.4f;

	public Heap heap;

	private Glowing glowing;
	//FIXME: a lot of this emitter functionality isn't very well implemented.
	//right now I want to ship 0.3.0, but should refactor in the future.
	protected Emitter emitter;
	private float phase;
	private boolean glowUp;

	private float dropInterval;

	//the amount the sprite is raised from flat when viewed in a raised perspective
	protected float perspectiveRaise    = 5 / 16f; //5 pixels

	//the width and height of the shadow are a percentage of sprite size
	//offset is the number of pixels the shadow is moved down or up (handy for some animations)
	protected boolean renderShadow  = false;
	protected float shadowWidth     = 1f;
	protected float shadowHeight    = 0.25f;
	protected float shadowOffset    = 0.5f;

	public ItemSprite() {
		this( GeneralAsset.SOMETHING, null );
	}

	public ItemSprite( Heap heap ){
		super();
		view( heap );
	}

	public ItemSprite( Item item ) {
		super();
		view( item );
	}

	public ItemSprite( Asset image ){
		this( image, null );
	}

	public ItemSprite( Asset image, Glowing glowing ) {
		super();
		view(image, glowing);
	}

	public void link() {
		link(heap);
	}

	public void link( Heap heap ) {
		this.heap = heap;
		view(heap);
		renderShadow = true;
		visible = heap.seen;
		place(heap.pos);
	}

	@Override
	public void revive() {
		super.revive();

		speed.set( 0 );
		acc.set( 0 );
		dropInterval = 0;

		heap = null;
		if (emitter != null) {
			emitter.killAndErase();
			emitter = null;
		}
	}

	public void visible(boolean value){
		this.visible = value;
		if (emitter != null && !visible){
			emitter.killAndErase();
			emitter = null;
		}
	}

	public PointF worldToCamera( int cell ) {
		final int csize = DungeonTilemap.SIZE;

		return new PointF(
				PixelScene.align(Camera.main, ((cell % Dungeon.level.width()) + 0.5f) * csize - width() * 0.5f),
				PixelScene.align(Camera.main, ((cell / Dungeon.level.width()) + 1.0f) * csize - height() - csize * perspectiveRaise)
		);
	}

	public void place( int p ) {
		if (Dungeon.level != null) {
			point(worldToCamera(p));
			shadowOffset = 0.5f;
		}
	}

	public void drop() {

		if (heap.isEmpty()) {
			return;
		} else if (heap.size() == 1){
			// normally this would happen for any heap, however this is not applied to heaps greater than 1 in size
			// in order to preserve an amusing visual bug/feature that used to trigger for heaps with size > 1
			// where as long as the player continually taps, the heap sails up into the air.
			place(heap.pos);
		}

		dropInterval = DROP_INTERVAL;

		speed.set( 0, -100 );
		acc.set(0, -speed.y / DROP_INTERVAL * 2);

		if (heap != null && heap.seen && heap.peek() instanceof Gold) {
			CellEmitter.center( heap.pos ).burst( Speck.factory( Speck.COIN ), 5 );
			Sample.INSTANCE.play( Assets.Sounds.GOLD, 1, 1, Random.Float( 0.9f, 1.1f ) );
		}
	}

	public void drop( int from ) {

		if (heap.pos == from) {
			drop();
		} else {

			float px = x;
			float py = y;
			drop();

			place(from);

			speed.offset((px - x) / DROP_INTERVAL, (py - y) / DROP_INTERVAL);
		}
	}

	public ItemSprite view( Item item ){
		view(item.image(), item.glowing());
		Emitter emitter = item.emitter();
		if (emitter != null && parent != null) {
			emitter.pos( this );
			parent.add( emitter );
			this.emitter = emitter;
		}
		return this;
	}

	public ItemSprite view( Heap heap ){
		if (heap.size() <= 0 || heap.items == null){
			return view( GeneralAsset.SOMETHING, null );
		}

		switch (heap.type) {
			case HEAP: case FOR_SALE:
				return view( heap.peek() );
			case CHEST:
				return view( GeneralAsset.CHEST, null );
			case LOCKED_CHEST:
				return view( GeneralAsset.LOCKED_CHEST, null );
			case CRYSTAL_CHEST:
				return view( GeneralAsset.CRYSTAL_CHEST, null );
			case TOMB:
				return view( GeneralAsset.TOMB, null );
			case SKELETON:
				return view( GeneralAsset.BONES, null );
			case REMAINS:
				return view( GeneralAsset.REMAINS, null );
			default:
				return view( GeneralAsset.SOMETHING, null );
		}
	}

	public ItemSprite view( Asset image, Glowing glowing ) {
		if (this.emitter != null) this.emitter.killAndErase();
		emitter = null;
		texture( Asset.getAssetFilePath(image) );
		glow( glowing );
		return this;
	}

	public synchronized void glow( Glowing glowing ){
		this.glowing = glowing;
		if (glowing == null) resetColor();
	}

	@Override
	public void kill() {
		super.kill();
		if (emitter != null) {
			emitter.on = false;
			emitter.autoKill = true;
		}
		emitter = null;
	}

	private float[] shadowMatrix = new float[16];

	@Override
	protected void updateMatrix() {
		super.updateMatrix();
		Matrix.copy(matrix, shadowMatrix);
		Matrix.translate(shadowMatrix,
				(width() * (1f - shadowWidth)) / 2f,
				(height() * (1f - shadowHeight)) + shadowOffset);
		Matrix.scale(shadowMatrix, shadowWidth, shadowHeight);
	}

	@Override
