	public void create() {

		Random.pushGenerator( Dungeon.seedCurDepth() );

		if (!(Dungeon.bossLevel())) {

			addItemToSpawn(Generator.random(Generator.Category.FOOD));

			if (Dungeon.isChallenged(Challenges.DARKNESS)){
				addItemToSpawn( new Torch() );
			}

			if (Arrays.asList(Dungeon.posLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new PotionOfStrength() );
			}
			if (Arrays.asList(Dungeon.souLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new ScrollOfUpgrade() );
			}
			if (Arrays.asList(Dungeon.asLevels).contains(Dungeon.levelName)) {
				addItemToSpawn( new Stylus() );
			}
			//one scroll of transmutation is guaranteed to spawn somewhere on chapter 2-4
			int enchChapter = (int)((Dungeon.seed / 10) % 3) + 1;
			if ( Dungeon.depth / 5 == enchChapter &&
					Dungeon.seed % 4 + 1 == Dungeon.depth % 5){
				addItemToSpawn( new StoneOfEnchantment() );
			}

			if ( Dungeon.depth == ((Dungeon.seed % 3) + 1)){
				addItemToSpawn( new StoneOfIntuition() );
			}

			switch (Dungeon.layout.getDungeon().get(Dungeon.levelName).getLevelFeeling()) {
				case "random":
					if (Dungeon.depth > 1) {
						//50% chance of getting a level feeling
						//~7.15% chance for each feeling
						switch (Random.Int( 14 )) {
							case 0:
								feeling = Feeling.CHASM;
								break;
							case 1:
								feeling = Feeling.WATER;
								break;
							case 2:
								feeling = Feeling.GRASS;
								break;
							case 3:
								feeling = Feeling.DARK;
								addItemToSpawn(new Torch());
								viewDistance = Math.round(viewDistance/2f);
								break;
							case 4:
								feeling = Feeling.LARGE;
								addItemToSpawn(Generator.random(Generator.Category.FOOD));
								//add a second torch to help with the larger floor
								if (Dungeon.isChallenged(Challenges.DARKNESS)){
									addItemToSpawn( new Torch() );
								}
								break;
							case 5:
								feeling = Feeling.TRAPS;
								break;
							case 6:
								feeling = Feeling.SECRETS;
								break;
						}
					}
					break;
				case "chasm":
					feeling = Feeling.CHASM;
					break;
				case "water":
					feeling = Feeling.WATER;
					break;
				case "grass":
					feeling = Feeling.GRASS;
					break;
				case "dark":
					feeling = Feeling.DARK;
					break;
				case "large":
					feeling = Feeling.LARGE;
					break;
				case "traps":
					feeling = Feeling.TRAPS;
					break;
				case "secrets":
					feeling = Feeling.SECRETS;
					break;
			}
		}

		do {
			width = height = length = 0;

			transitions = new ArrayList<>();

			mobs = new HashSet<>();
			heaps = new SparseArray<>();
			blobs = new HashMap<>();
			plants = new SparseArray<>();
			traps = new SparseArray<>();
			customTiles = new HashSet<>();
			customWalls = new HashSet<>();

		} while (!build());

		buildFlagMaps();
		cleanWalls();

		createMobs();
		createItems();

		switch (Dungeon.layout.getDungeon().get(Dungeon.levelName).getVisibility()) {
			case ONLY_VISIBLE:
				for (int i=0; i < length; i++) {
					if (discoverable[i]) {
						visited[i] = true;
					}
				}
				GameScene.updateFog();
				break;
			case SECRETS:
				for (int i=0; i < length; i++) {
					int terr = map[i];
					if (discoverable[i]) {
						visited[i] = true;
						if ((Terrain.flags[terr] & Terrain.SECRET) != 0) {
							discover( i );
						}
					}
				}
				GameScene.updateFog();
				break;
		}

		Random.popGenerator();
	}

	public void setSize(int w, int h){

		width = w;
		height = h;
		length = w * h;

		map = new int[length];
		Arrays.fill( map, feeling == Level.Feeling.CHASM ? Terrain.CHASM : Terrain.WALL );

		visited     = new boolean[length];
		mapped      = new boolean[length];

		heroFOV     = new boolean[length];

		passable	= new boolean[length];
		losBlocking	= new boolean[length];
		flamable	= new boolean[length];
		secret		= new boolean[length];
		solid		= new boolean[length];
		avoid		= new boolean[length];
		water		= new boolean[length];
		pit			= new boolean[length];

		openSpace   = new boolean[length];

		PathFinder.setMapSize(w, h);
	}

	public void reset() {

		for (Mob mob : mobs.toArray( new Mob[0] )) {
			if (!mob.reset()) {
				mobs.remove( mob );
			}
		}
		createMobs();
	}

