					door.y = rooms[0].center().y;
				} else {
					door.y = rooms[2].center().y;
				}
			} else {
				if (door.x < center.x){
					door.x = rooms[0].center().x;
				} else {
					door.x = rooms[1].center().x;
				}
			}
			Painter.set(level, door, Terrain.CRYSTAL_DOOR);
			door.x -= center.x;
			door.y -= center.y;
			int tmp = door.x;
			door.x = door.y;
			door.y = tmp;
			if (clockwise)  door.x = -door.x;
